require "test_helper"

class CoachApp::PasswordTest < ActiveSupport::TestCase
  # Generated by bcryptjs 2.4.3 at cost 12, the library the Node API hashes passwords with.
  NODE_HASH = "$2a$12$gVjeJT.E1dAjYIbStBByCenFyH2u990j7idUMYXH14rsKJ0/xIc8S"
  NODE_ARABIC_HASH = "$2a$12$nAQn3xzxNTqO8d1Zl8bowOghhkDtxKjiHpBdf8ipPzT5o/nQikBQ."

  test "verifies a password Node hashed" do
    assert CoachApp::Password.verify("Demo@12345", NODE_HASH)
  end

  test "verifies an Arabic password Node hashed" do
    assert CoachApp::Password.verify("كلمةسر١٢٣٤٥", NODE_ARABIC_HASH)
  end

  test "refuses the wrong password" do
    assert_not CoachApp::Password.verify("wrong", NODE_HASH)
  end

  test "a malformed stored hash is a refusal, not an error" do
    assert_not CoachApp::Password.verify("x", "x")
  end

  test "text after a null byte still counts" do
    assert_not CoachApp::Password.verify("Demo@12345\u0000extra", NODE_HASH)
  end

  test "input that is not a string is a refusal" do
    assert_not CoachApp::Password.verify(nil, NODE_HASH)
    assert_not CoachApp::Password.verify(12345678, NODE_HASH)
  end

  test "digest refuses a null byte, which bcrypt would silently cut the password at" do
    assert_raises(ArgumentError) { CoachApp::Password.digest("Demo@12345\u0000extra") }
  end

  test "digest uses cost 12 and verifies" do
    hashed = CoachApp::Password.digest("كلمةسر-جديدة")

    assert_equal 12, BCrypt::Password.new(hashed).cost
    assert CoachApp::Password.verify("كلمةسر-جديدة", hashed)
  end
end
